"""Build the LLEO static site with Python 3; no third-party dependencies."""
from pathlib import Path
from html import escape
import json
import re
ROOT=Path(__file__).parent
SITE='https://AdamAnderB.github.io/lleo-lab/'
REPO='https://github.com/AdamAnderB/lleo-lab'
# Remove stale generated profiles when a member withdraws visibility.
for old in ROOT.glob('person-*.html'): old.unlink()
def link(url,label): return f'<a href="{escape(url,quote=True)}">{escape(label)} ↗</a>'
def card(title,text,url,label='Explore'):
 return f'<article class="card"><h3>{escape(title)}</h3><p>{text}</p>{link(url,label)}</article>'
nav=[('index','Home'),('research','Research'),('projects','Projects'),('people','People'),('publications','Publications'),('resources','Resources'),('contact','Contact')]
def page(slug,title,body,kicker='LLEO LAB',intro=''):
 n=''.join(f'<a href="{s}.html" '+('aria-current="page"' if s==slug else '')+f'>{t}</a>' for s,t in nav)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(re.sub(r"<[^>]+>", " ", title))} · LLEO Lab</title><meta name="description" content="{escape(intro or 'Learning, Language, Exploration, Observation. Research, people, and open methods.',quote=True)}"><link rel="stylesheet" href="assets/style.css"><link rel="icon" href="data:,"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html">LLEO<span>LAB</span></a><nav aria-label="Main navigation">{n}</nav></header><main id="main"><div class="page-head"><p class="eyebrow">{kicker}</p><h1>{title}</h1>{f'<p class="intro">{intro}</p>' if intro else ''}</div>{body}</main><footer><div><b>LLEO Lab</b><p>Learning · Language · Exploration · Observation</p></div><div>{link('https://www.adamabramlett.com/','Adam’s personal site')}<br>{link(REPO,'Lab workspace on GitHub')}</div><p class="fine">A growing research home. Public pages are open to everyone; project access is managed on GitHub.</p></footer></body></html>'''
 (ROOT/f'{slug}.html').write_text(html)
branches=[('learning','Learning','How does what we know shape what we can learn?','Prior experience can support new learning, but it can also make useful information harder to notice. We connect cue learning, prediction error, adaptation, and lexical experience.','Compare learning histories, track changing cue use, and test how knowledge transfers to a new vocabulary.'),('language','Language','How do listeners turn unfolding sound into words?','Speech varies across speakers, contexts, and languages. We study how listeners recognize words, learn unfamiliar contrasts, and use the information carried by speech.','Connect speech perception and word recognition through behavioral experiments and computational accounts.'),('exploration','Exploration','What can we discover by making a theory runnable?','Models and interactive tools let us inspect assumptions, follow their consequences, and ask which new experiments would distinguish competing explanations.','Simulate learning and recognition, explore acoustic stimuli, and make research tools useful to other learners.'),('observation','Observation','How do we turn behavior into trustworthy evidence?','The details of measurement matter. Eye movements, response times, acoustic measurements, and transparent analysis help us connect theoretical questions to observable behavior.','Build reproducible experiments, examine data-processing decisions, and use replication to sharpen what we can conclude.')]
branchcards=''.join(card(t,q,s+'.html','Explore '+t.lower()) for s,t,q,_,_ in branches)
page('index','Knowing changes<br><em>learning.</em>',f'''<section class="hero"><div><p class="lead">How does what we know shape what we can learn?</p><p>LLEO brings together questions about learning and language with the tools to explore them and the observations to test them.</p><div class="actions"><a class="button" href="research.html">Explore our research</a><a href="resources.html">Start learning with us →</a></div></div><figure><img src="assets/lleo-logo.png" alt="LLEO Lab logo: a curious dog above the Learning, Language, Exploration, Observation wordmark" width="1983" height="793"><figcaption>Curiosity is a good place to start.</figcaption></figure></section><section><div class="section-label">FOUR CONNECTED PERSPECTIVES</div><div class="grid four">{branchcards}</div></section><section class="feature"><div><p class="eyebrow">FEATURED FOUNDATION · DISSERTATION RESEARCH</p><h2>Knowing and Learning</h2><p>When does existing knowledge help—and when does it hold us back? Explore experiments on learning history, speech cues, and word learning.</p>{link('https://github.com/AdamAnderB/knowing-and-learning','Explore the dissertation repository')}</div><div class="big-letters" aria-hidden="true">L L<br>E O</div></section><section><h2>A place to ask, build, and share.</h2><p class="measure">Research takes people as well as ideas. Our handbook introduces the practical side: joining a project, learning Git, building experiments in Gorilla, and giving contributors visible credit.</p><a href="handbook.html">Open the lab handbook →</a></section>''',intro='Learning, Language, Exploration, Observation')
page('research','Four branches.<br><em>Shared questions.</em>',f'<p class="lead">These are connected perspectives, not separate departments. A single project can live across several branches.</p><div class="grid two">{branchcards}</div>')
for s,t,q,d,m in branches:
 page(s,t,f'<p class="lead">{q}</p><div class="prose"><p>{d}</p><h2>How we investigate</h2><p>{m}</p><h2>Follow the connections</h2><p>Explore the dissertation, earlier studies, and open tools in our project collection.</p><a href="projects.html">View projects and foundations →</a></div><div class="branch-nav">'+''.join(link(b+'.html',a) for b,a,*_ in branches if b!=s)+'</div>',kicker='RESEARCH / '+t.upper())
projects=[('Knowing and Learning','Dissertation research · Learning + Language','Statistical analyses for Chapters 2 and 3, with links to models and acoustic-stimulus exploration.','https://github.com/AdamAnderB/knowing-and-learning'),('The Art of Wrangling','Prior collaborative work · Observation','Adam A. Bramlett and Seth Wiener’s reproducible workflow for web-based visual world eye-tracking research.','https://github.com/AdamAnderB/AoW'),('Spoken-word recognition with jTRACE','Prior collaborative work · Language + Exploration','Adam A. Bramlett and Seth Wiener’s 2022 work on L2 Mandarin spoken-word recognition at two learning time points.','https://www.adamabramlett.com/research')]
page('projects','Questions become projects.','<section><h2>Current LLEO projects</h2><p>No new LLEO studies are announced here yet. A project enters this directory when its lead, scope, public summary, and sharing permissions are confirmed.</p>'+link(REPO+'/tree/main/templates/project','Start a project with the template')+'</section><section><h2>Dissertation &amp; prior work</h2><p>These foundations retain their original authorship and provenance. They are not relabeled as new LLEO studies.</p><div class="grid">'+''.join(card(t,f'<span class="tag">{k}</span><br>{d}',u) for t,k,d,u in projects)+'</div></section>')
members=json.loads((ROOT/'members.json').read_text())
membercards=''
for p in members:
 if not p.get('public'): continue
 slug='person-'+p['slug']; membercards+=card(p['name'],escape(p['role'])+'<br>'+escape(p['bio']),slug+'.html','View profile')
 page(slug,escape(p['name']),'<div class="prose"><p class="eyebrow">'+escape(p['role'])+'</p><p class="lead">'+escape(p['bio'])+'</p><h2>Research &amp; connections</h2><p>'+ ' · '.join(link(u,l) for l,u in p['links'].items())+'</p><h2>Work connected to LLEO</h2><p><a href="projects.html">Dissertation research and prior collaborative work →</a></p></div>',kicker='PEOPLE / MEMBER PROFILE')
page('people','Research grows<br><em>with people.</em>','<div class="grid">'+membercards+'</div><section class="prose"><h2>Members, collaborators, and alumni</h2><p>Members actively belong to the lab; collaborators join particular projects; alumni remain part of its history. Earlier coauthorship alone does not imply current lab membership.</p><h2>Your work, your profile</h2><p>Members can choose a short listing, a full profile, or no public listing. Profiles can link to personal websites, GitHub, CVs, projects, and outputs. We publish names and photographs only with permission.</p>'+link(REPO+'/tree/main/templates/member','Member profile guide')+'</section>')
page('publications','Work you can follow.','<div class="prose"><p class="lead">Selected prior work that informs LLEO’s questions and methods.</p><article class="citation"><span class="tag">2025 · JOURNAL ARTICLE · PRIOR WORK</span><h2>The art of wrangling</h2><p>Bramlett, A. A., &amp; Wiener, S. Working with web-based visual world paradigm eye-tracking data in language research. <i>Linguistic Approaches to Bilingualism, 15</i>(4), 538–570. First published online in 2024.</p>'+link('https://doi.org/10.1075/lab.23071.bra','Publisher / DOI')+' · '+link('https://github.com/AdamAnderB/AoW','Code')+'</article><article class="citation"><span class="tag">2022 · CONFERENCE WORK · PRIOR WORK</span><h2>jTRACE modeling of L2 Mandarin learners’ spoken word recognition at two time points in learning</h2><p>Adam A. Bramlett &amp; Seth Wiener. Speech Prosody 2022.</p>'+link('https://www.adamabramlett.com/research','Poster, paper, and abstract links')+'</article><h2>More research</h2><p>'+link('https://www.adamabramlett.com/research','Adam’s research archive')+'</p><p>New lab publications will be added with their full author list, stable citation, and available materials.</p></div>')
apps=[('Acoustic stimulus explorer','Explore stimuli connected to the dissertation’s learning experiments.','https://adam-a-bramlett.shinyapps.io/stimuli_exploration/'),('Eye Fixations App','Explore how data-removal thresholds affect eye-fixation distributions.','https://adam-a-bramlett.shinyapps.io/Eye_Fixations_App/'),('Frame Rate App','Explore frame-rate thresholds and time-bin choices for eye-tracking data.','https://adam-a-bramlett.shinyapps.io/Frame_Rate_App/')]
page('resources','Tools for curious minds.','<section><h2>Explore with Shiny</h2><p>Interactive tools from Adam’s dissertation and earlier collaborative work. Hosted apps may take a moment to wake up.</p><div class="grid">'+''.join(card(t,d,u,'Open app') for t,d,u in apps)+'</div><p>'+link('https://github.com/AdamAnderB/Eye_Fixations_App','Eye Fixations source')+' · '+link('https://github.com/AdamAnderB/Frame_Rate_App','Frame Rate source')+'</p></section><section><h2>Learn the lab workflow</h2><div class="grid">'+card('Lab handbook','Your first contribution, project lifecycle, and responsible sharing.','handbook.html','Read the handbook')+card('R as a Second Language','Learning materials from Adam’s public repository.','https://github.com/AdamAnderB/R-as-a-Second-Language','View materials')+card('Gorilla open materials','Explore materials associated with The Art of Wrangling.','https://app.gorilla.sc/openmaterials/715241','View experiment materials')+'</div></section>')
page('contact','Let’s follow a question.','<div class="prose"><p class="lead">Interested in learning, language, research tools, or a possible collaboration?</p><p>Contact Adam A. Bramlett with a short introduction and the question or project you would like to explore. Student inquiries are welcome; this is not an announcement of a funded position.</p><p>'+link('mailto:abramlet@andrew.cmu.edu','Email Adam')+'</p><p>'+link('https://www.adamabramlett.com/','Personal website')+'</p><h2>Already contributing?</h2><p>Use the lab repository for public website fixes and non-sensitive project proposals. Access to private research work is arranged individually.</p>'+link(REPO,'Open the GitHub workspace')+'</div>')
page('handbook','A shared way of working.','<div class="prose"><p class="lead">Start small. Make your work understandable. Give people credit.</p><ol><li>Create your own GitHub account, enable two-factor authentication, and share your username with the project lead.</li><li>Read the public/private policy before uploading anything.</li><li>Practice a small edit on a branch and open a pull request.</li><li>Agree on your project question, responsibilities, and storage with the lead.</li><li>Choose whether and how you want to appear on the People page.</li></ol><h2>Handbook chapters</h2><ul>'+''.join('<li>'+link(REPO+'/blob/main/handbook/'+f,t)+'</li>' for f,t in [('onboarding.md','First week & Git basics'),('gorilla.md','Building and piloting in Gorilla'),('projects.md','Starting, running, and closing projects'),('public-private.md','Public/private data policy'),('members.md','Profiles, credit, and offboarding')])+'</ul><h2>Before the first commit</h2><p>This repository and its history are public. Do not upload participant records, credentials, consent forms, identifying recordings, or private lab notes. A private GitHub repository is not a substitute for approved research-data storage.</p></div>')
print('Built',len(list(ROOT.glob('*.html'))),'pages')
